const results = await Promise.allSettled([
  tools.exec_command({cmd:"cat README.md && cat skills/travel-expense-claim/SKILL.md && cat pyproject.toml",workdir:"/home/maxg/travel-expense-claim",yield_time_ms:10000,max_output_tokens:9000}),
  tools.exec_command({cmd:"sed -n '1,260p' src/travel_claim/cli.py && sed -n '1,200p' src/main.py && cat tests/test_validate_snapshot.py",workdir:"/home/maxg/travel-expense-claim",yield_time_ms:10000,max_output_tokens:12000}),
  tools.exec_command({cmd:"cat snapshot.schema.json && sed -n '1,280p' interviews/project-d-travel-expense-claim-20261013-2210.md",workdir:"/home/maxg/travel-expense-claim",yield_time_ms:10000,max_output_tokens:15000}),
  tools.exec_command({cmd:"find . -maxdepth 5 -type f -not -path './.git/*' -print | sort && git branch -a && git log --all --oneline --decorate -15",workdir:"/home/maxg/travel-expense-claim",yield_time_ms:10000,max_output_tokens:5000})
]);
for (let i=0;i<results.length;i++) { let x=results[i]; text(`--- RESULT ${i+1} ---\n${x.status==="fulfilled"?x.value.output:String(x.reason)}`); }

