from pathlib import Path
from typing import Callable, Mapping


@dataclass(frozen=True)
class NativeSource:
    source_id: str
    title: str
    url: str
    locator: str
    export_url: str | None = None
    kind: str = "binary"


SOURCES: tuple[NativeSource, ...] = (
