"""Policy-neutral structural workflow primitives.

These helpers preserve submitted revisions and identify linked events. They do
not evaluate policy, recommend/record approval, calculate entitlement, or
declare any claim ready or reimbursed.
"""

from __future__ import annotations

from collections import defaultdict
from typing import Any


def row_values(record: dict[str, Any]) -> dict[str, Any]:
    """Flatten one parsed workbook row to its recorded cell values."""
    return {key: cell.get("value") for key, cell in record.get("values", {}).items()}


def _revision(value: Any) -> int | None:
    if isinstance(value, bool) or value is None:
        return None
    try:
        number = int(value)
    except (ValueError, TypeError, OverflowError):
        return None
    if number < 1 or float(value) != number:
        return None
    return number


def _source_ref(record: dict[str, Any]) -> dict[str, Any]:
    return {key: record.get(key) for key in ("source_id", "source_sha256", "locator")}


def build_revision_history(parsed: dict[str, Any]) -> dict[str, Any]:
    """Build complete claim/trip/permit revision indexes with source refs.

    `current_revision` is only the greatest source-observed revision number.
    It is not a judgement that the record is complete, valid, or policy-ready.
    """
    groups: dict[str, dict[str, list[dict[str, Any]]]] = {
        "claim": defaultdict(list), "trip": defaultdict(list), "permit": defaultdict(list)
    }
    malformed = []
    for record in parsed["records"].get("claim_revisions", []):
        values = {field["label"].strip(): field["value"] for field in record.get("fields", [])}
        subject_id = values.get("Claim reference")
        revision = _revision(values.get("Revision"))
        if not subject_id or revision is None:
            malformed.append({"kind": "claim", "source_ref": _source_ref(record), "reason": "missing subject ID or positive revision"})
            continue
        groups["claim"][str(subject_id)].append({
            "subject_id": str(subject_id), "revision": revision,
            "trip_id": values.get("Trip reference"),
            "trip_revision": _revision(values.get("Trip revision")),
            "arrival_batch": values.get("Arrival batch"),
            "record": record, "source_ref": _source_ref(record),
        })
    for record in parsed["records"].get("trips", []):
        values = row_values(record)
        subject_id = values.get("Trip reference")
        revision = _revision(values.get("Trip revision"))
        if not subject_id or revision is None:
            malformed.append({"kind": "trip", "source_ref": _source_ref(record), "reason": "missing subject ID or positive revision"})
            continue
        groups["trip"][str(subject_id)].append({
            "subject_id": str(subject_id), "revision": revision,
            "permit_id": values.get("Permit reference"),
            "permit_revision": _revision(values.get("Permit revision")),
            "record": record, "source_ref": _source_ref(record),
        })
        permit_id = values.get("Permit reference")
        if permit_id is not None and permit_id != "":
            permit_revision = _revision(values.get("Permit revision"))
            if permit_revision is None:
                malformed.append({"kind": "permit", "source_ref": _source_ref(record), "reason": "permit reference has no positive permit revision"})
            else:
                groups["permit"][str(permit_id)].append({
                    "subject_id": str(permit_id), "revision": permit_revision,
                    "trip_id": str(subject_id), "trip_revision": revision,
                    "record": record, "source_ref": _source_ref(record),
                })

    result: dict[str, Any] = {"revision_semantics": "source-observed maximum only; no business readiness conclusion"}
    conflicts = []
    for kind, subjects in groups.items():
        indexed = {}
        for subject_id, revisions in subjects.items():
            revisions.sort(key=lambda item: (item["revision"], item["source_ref"].get("locator") or ""))
            seen: dict[int, list[dict[str, Any]]] = defaultdict(list)
            for item in revisions:
                seen[item["revision"]].append(item)
            for rev, same in seen.items():
                if len(same) > 1:
                    # Repeated records can be source retransmissions. Retain
                    # every occurrence and surface it for later comparison.
                    conflicts.append({"kind": kind, "subject_id": subject_id, "revision": rev,
                                      "occurrences": [item["source_ref"] for item in same]})
            indexed[subject_id] = {
                "current_revision": max(item["revision"] for item in revisions),
                "revisions": revisions,
            }
        result[kind] = indexed
    result["issues"] = {"malformed_revision_records": malformed, "repeated_subject_revisions": conflicts}
    return result


def match_decisions_to_subjects(decisions: list[dict[str, Any]], history: dict[str, Any]) -> list[dict[str, Any]]:
    """Match review ledger identities and revisions without applying outcomes."""
    matches = []
    for record in decisions:
        values = row_values(record)
        decision_id = values.get("Decision reference")
        kind = values.get("Subject type")
        subject_id = values.get("Subject reference")
        revision = _revision(values.get("Revision"))
        target_kind = str(kind) if kind in {"claim", "trip", "permit"} else None
        target = history.get(target_kind, {}).get(str(subject_id)) if target_kind and subject_id else None
        if target is None:
            result = "unsupported_subject_type" if target_kind is None else "subject_not_found"
            source_refs = []
        elif revision is None:
            result = "invalid_revision"
            source_refs = []
        else:
            occurrences = [item for item in target["revisions"] if item["revision"] == revision]
            if not occurrences:
                result = "revision_not_found"
                source_refs = []
            else:
                result = "revision_match_current" if revision == target["current_revision"] else "revision_match_historical"
                source_refs = [item["source_ref"] for item in occurrences]
        matches.append({
            "decision_id": decision_id,
            "subject_type": kind,
            "subject_id": subject_id,
            "revision": revision,
            "observed_outcome": values.get("Outcome"),
            "structural_match": result,
            "matched_source_refs": source_refs,
            "decision_source_ref": _source_ref(record),
            "applied": False,
        })
    return matches


def _business_payload(record: dict[str, Any], id_field: str, ignore_fields: set[str]) -> dict[str, Any]:
    values = row_values(record)
    return {key: values[key] for key in sorted(values) if key != id_field and key not in ignore_fields}


def deduplicate_activity_records(
    records: list[dict[str, Any]], *, id_field: str, ignore_fields: tuple[str, ...] = ("Arrival batch",)
) -> dict[str, Any]:
    """Deduplicate immutable event IDs, ignoring only declared delivery fields.

    All source occurrences remain cited. A differing business payload for an
    existing ID is reported as a conflict and never replaces the first event.
    """
    by_id: dict[str, list[dict[str, Any]]] = defaultdict(list)
    missing_id = []
    for record in records:
        event_id = row_values(record).get(id_field)
        if not isinstance(event_id, str) or not event_id:
            missing_id.append({"source_ref": _source_ref(record), "reason": f"missing {id_field}"})
        else:
            by_id[event_id].append(record)
    admitted, duplicates, conflicts = [], [], []
    for event_id, occurrences in by_id.items():
        first = occurrences[0]
        first_payload = _business_payload(first, id_field, set(ignore_fields))
        disagree = [row for row in occurrences[1:]
                    if _business_payload(row, id_field, set(ignore_fields)) != first_payload]
        refs = [_source_ref(row) for row in occurrences]
        if disagree:
            conflicts.append({"event_id": event_id, "id_field": id_field,
                              "occurrences": refs,
                              "payloads": [first_payload] + [_business_payload(row, id_field, set(ignore_fields)) for row in disagree]})
            continue
        admitted.append(first)
        if len(occurrences) > 1:
            duplicates.append({"event_id": event_id, "id_field": id_field,
                               "source_occurrences": refs,
                               "delivery_batches": [row_values(row).get("Arrival batch") for row in occurrences]})
    return {"unique_events": admitted, "duplicates": duplicates, "conflicts": conflicts, "missing_ids": missing_id}


def reduce_cancellation_activities(records: list[dict[str, Any]]) -> dict[str, Any]:
    """Track independent trip/permit cancellation requests and confirmations.

    Ordering uses supplied arrival batch then workbook row, never activity
    timestamps. A confirmed action is structural only; it does not settle any
    claim or Finance obligation.
    """
    dedup = deduplicate_activity_records(records, id_field="Cancellation activity reference")
    conflicting_ids = {issue["event_id"] for issue in dedup["conflicts"]}
    events = [record for record in dedup["unique_events"]
              if row_values(record).get("Cancellation activity reference") not in conflicting_ids]
    events.sort(key=lambda row: (
        _revision(row_values(row).get("Arrival batch")) or 0,
        row.get("row", 0),
    ))
    processes: dict[str, dict[str, Any]] = {}
    issues = list(dedup["conflicts"])
    id_lookup: dict[str, tuple[str, dict[str, Any]]] = {}
    for record in events:
        values = row_values(record)
        event_id = values.get("Cancellation activity reference")
        cancellation_id = values.get("Cancellation reference")
        action = values.get("Action")
        subject_type = values.get("Cancelled subject")
        if not cancellation_id or subject_type not in {"trip", "permit"}:
            issues.append({"event_id": event_id, "source_ref": _source_ref(record), "reason": "missing cancellation ID or unsupported target type"})
            continue
        target_id = values.get("Trip reference") if subject_type == "trip" else values.get("Permit reference")
        target_revision = _revision(values.get("Trip revision") if subject_type == "trip" else values.get("Permit revision"))
        target = {"subject_type": subject_type, "subject_id": target_id, "revision": target_revision}
        process = processes.setdefault(str(cancellation_id), {
            "cancellation_id": cancellation_id, "target": target, "state": "unseen",
            "activity_ids": [], "history": [], "next_action": "await request activity",
        })
        if process["target"] != target:
            issues.append({"cancellation_id": cancellation_id, "event_id": event_id,
                           "source_ref": _source_ref(record), "reason": "cancellation target identity/revision conflicts with prior activity"})
            continue
        if action == "requested":
            if process["state"] != "unseen":
                issues.append({"cancellation_id": cancellation_id, "event_id": event_id,
                               "source_ref": _source_ref(record), "reason": f"request is not valid after state {process['state']}"})
                continue
            process["state"] = "requested"
            process["next_action"] = "await a linked confirmation activity"
        elif action == "confirmed":
            initiation = values.get("Initiation activity reference")
            linked = id_lookup.get(str(initiation)) if initiation else None
            if process["state"] != "requested" or not linked or linked[0] != cancellation_id or row_values(linked[1]).get("Action") != "requested":
                issues.append({"cancellation_id": cancellation_id, "event_id": event_id,
                               "source_ref": _source_ref(record), "reason": "confirmation does not link to a prior request activity"})
                continue
            if not values.get("Effective time (UTC)"):
                process["state"] = "requested"
                process["next_action"] = "obtain the missing effective time or confirmation record"
                issues.append({"cancellation_id": cancellation_id, "event_id": event_id,
                               "source_ref": _source_ref(record), "reason": "confirmation has no effective time"})
                continue
            process["state"] = "confirmed"
            process["next_action"] = None
        else:
            issues.append({"cancellation_id": cancellation_id, "event_id": event_id,
                           "source_ref": _source_ref(record), "reason": f"unsupported action {action!r}"})
            continue
        process["activity_ids"].append(event_id)
        process["history"].append({
            "event_id": event_id, "action": action,
            "arrival_batch": values.get("Arrival batch"),
            "effective_time": values.get("Effective time (UTC)"),
            "source_ref": _source_ref(record),
        })
        id_lookup[str(event_id)] = (str(cancellation_id), record)
    return {"processes": processes, "issues": issues,
            "duplicate_events": dedup["duplicates"], "conflicting_events": dedup["conflicts"],
            "finance_effects": [], "claim_effects": []}
"""Schema-checked, content-addressed batch snapshots."""

from __future__ import annotations

import copy
import json
from pathlib import Path

from jsonschema import Draft202012Validator, FormatChecker

from .sources import sha256_bytes, verify_source_manifest


def _schema_errors(snapshot: dict, schema_path: Path) -> list[str]:
    schema = json.loads(schema_path.read_text(encoding="utf-8"))
    validator = Draft202012Validator(schema, format_checker=FormatChecker())
    return [
        f"{'.'.join(map(str, err.absolute_path)) or '<root>'}: {err.message}"
        for err in sorted(validator.iter_errors(snapshot), key=lambda e: list(map(str, e.absolute_path)))
    ]


def _check_semantics(snapshot: dict) -> list[str]:
    errors: list[str] = []
    issue_ids = [issue["record_id"] for issue in snapshot["issues"]]
    if len(issue_ids) != len(set(issue_ids)):
        errors.append("issues[].record_id values must be unique")
    issue_set = set(issue_ids)
    for cancellation in snapshot["travel_cancellations"]:
        missing = set(cancellation["issue_record_ids"]) - issue_set
        if missing:
            errors.append(f"cancellation {cancellation['cancellation_id']} refers to missing issue records: {sorted(missing)}")
    claim_ids = {claim["claim_id"] for claim in snapshot["claims"]}
    for request in snapshot["requests"]:
        if request["claim_id"] not in claim_ids:
            errors.append(f"request {request['request_id']} refers to missing claim {request['claim_id']}")
    cancellation_event_ids = {
        event_id
        for cancellation in snapshot["travel_cancellations"]
        for event_id in cancellation["admitted_cancellation_event_ids"]
    }
    overlap = cancellation_event_ids & set(snapshot["admitted_event_ids"])
    if overlap:
        errors.append(f"Finance admitted_event_ids must not contain cancellation activity IDs: {sorted(overlap)}")
    return errors


def verify_snapshot(snapshot_path: Path, run_dir: Path, schema_path: Path) -> list[str]:
    """Verify this snapshot and every sealed snapshot in its predecessor chain."""
    return _verify_snapshot(snapshot_path, run_dir, schema_path, set())


def _verify_snapshot(
    snapshot_path: Path,
    run_dir: Path,
    schema_path: Path,
    seen_paths: set[Path],
) -> list[str]:
    """Validate schema plus source/predecessor hashes and required references."""
    resolved_snapshot = snapshot_path.resolve()
    if resolved_snapshot in seen_paths:
        return [f"predecessor cycle detected at {snapshot_path}"]
    seen_paths.add(resolved_snapshot)
    try:
        snapshot = json.loads(snapshot_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        return [f"Cannot read snapshot: {exc}"]
    errors = _schema_errors(snapshot, schema_path)
    if errors:
        return errors
    errors.extend(_check_semantics(snapshot))
    errors.extend(verify_source_manifest(run_dir))
    try:
        manifest = json.loads((run_dir / "sources.json").read_text(encoding="utf-8"))
        if not isinstance(manifest, dict):
            raise ValueError("sources.json must be an object")
        if manifest.get("run_id") != snapshot["run_id"]:
            errors.append("snapshot run_id does not match sources.json run_id")
        files = manifest.get("files", [])
        retained_ids = {
            record.get("source_id")
            for record in files if isinstance(record, dict)
            if record.get("status") == "read"
        }
        for claim in snapshot["claims"]:
            for line in claim["lines"]:
                missing_sources = set(line["source_ids"]) - retained_ids
                if missing_sources:
                    errors.append(
                        f"claim {claim['claim_id']} cost {line['cost_id']} refers to unavailable source IDs: {sorted(missing_sources)}"
                    )
    except (OSError, json.JSONDecodeError, ValueError):
        manifest = {}
    source_binding = snapshot["source_binding"]
    source_path = run_dir / source_binding["path"]
    if not source_path.resolve().is_relative_to(run_dir.resolve()):
        errors.append("source_binding path escapes the run directory")
        return errors
    if source_path.resolve() != (run_dir / "sources.json").resolve():
        errors.append("source_binding must identify this run's sources.json")
        return errors
    try:
        actual = sha256_bytes(source_path.read_bytes())
    except OSError as exc:
        errors.append(f"Cannot read bound sources file {source_binding['path']}: {exc}")
    else:
        if actual != source_binding["sha256"]:
            errors.append("source_binding SHA-256 does not match retained sources.json")
    predecessor = snapshot["predecessor"]
    if predecessor is not None:
        previous_path = run_dir / predecessor["path"]
        if not previous_path.resolve().is_relative_to((run_dir / "batches").resolve()):
            errors.append("predecessor path escapes the run's batches directory")
            return errors
        try:
            actual = sha256_bytes(previous_path.read_bytes())
        except OSError as exc:
            errors.append(f"Cannot read predecessor {predecessor['path']}: {exc}")
        else:
            if actual != predecessor["sha256"]:
                errors.append("predecessor SHA-256 does not match retained snapshot")
            else:
                errors.extend(
                    f"predecessor chain: {error}"
                    for error in _verify_snapshot(previous_path, run_dir, schema_path, seen_paths)
                )
    return errors


def seal_batch_snapshot(
    run_dir: Path,
    *,
    run_id: str,
    batch_id: str,
    claims: list[dict],
    requests: list[dict],
    travel_cancellations: list[dict],
    admitted_event_ids: list[str],
    issues: list[dict],
    schema_path: Path,
    predecessor_path: Path | None = None,
) -> Path:
    """Seal one batch. Binding paths are relative to the run directory.

    Existing snapshots are never overwritten. The first snapshot uses a null
    predecessor; later snapshots hash the exact prior serialized bytes.
    """
    batches_dir = run_dir / "batches"
    batches_dir.mkdir(parents=True, exist_ok=True)
    if not batch_id or Path(batch_id).name != batch_id or batch_id in {".", ".."}:
        raise ValueError("batch_id must be a single safe path component")
    target = batches_dir / f"{batch_id}.json"
    if target.exists():
        raise FileExistsError(f"Refusing to overwrite sealed snapshot: {target}")
    source_path = run_dir / "sources.json"
    if not source_path.is_file():
        raise FileNotFoundError(f"Required source manifest missing: {source_path}")
    source_errors = verify_source_manifest(run_dir)
    if source_errors:
        raise ValueError("Source manifest is not integrity-valid: " + "; ".join(source_errors))
    manifest = json.loads(source_path.read_text(encoding="utf-8"))
    if manifest.get("run_id") != run_id:
        raise ValueError("Snapshot run_id must match sources.json run_id")
    if not manifest.get("case_clock"):
        raise ValueError("Cannot consume a batch without the supplied scenario case_clock")
    existing_snapshots = list(batches_dir.glob("*.json"))
    if existing_snapshots and predecessor_path is None:
        raise ValueError("A later batch must bind its predecessor snapshot")
    source_rel = Path("sources.json")
    predecessor = None
    if predecessor_path is not None:
        predecessor_path = predecessor_path.resolve()
        if not predecessor_path.is_file():
            raise FileNotFoundError(f"Predecessor snapshot missing: {predecessor_path}")
        if predecessor_path.parent.resolve() != batches_dir.resolve():
            raise ValueError("Predecessor must be a retained snapshot in this run's batches directory")
        # Verify its source binding and full schema before chaining from it.
        predecessor_errors = verify_snapshot(predecessor_path, run_dir, schema_path)
        if predecessor_errors:
            raise ValueError("Predecessor snapshot is invalid: " + "; ".join(predecessor_errors))
        prior_state = json.loads(predecessor_path.read_text(encoding="utf-8"))
        if prior_state["run_id"] != run_id:
            raise ValueError("Predecessor snapshot belongs to a different run")
        chain_paths: set[Path] = set()
        cursor = predecessor_path.resolve()
        while cursor not in chain_paths:
            chain_paths.add(cursor)
            cursor_state = json.loads(cursor.read_text(encoding="utf-8"))
            previous = cursor_state["predecessor"]
            if previous is None:
                break
            cursor = (run_dir / previous["path"]).resolve()
        existing_paths = {path.resolve() for path in existing_snapshots}
        if chain_paths != existing_paths:
            raise ValueError("Predecessor must be the end of the complete retained snapshot chain; orphaned or missing prior state found")
        predecessor = {
            "path": (Path("batches") / predecessor_path.name).as_posix(),
            "sha256": sha256_bytes(predecessor_path.read_bytes()),
        }
    snapshot = {
        "schema_version": "travel-claim-snapshot/2",
        "run_id": run_id,
        "batch_id": batch_id,
        "predecessor": predecessor,
        "source_binding": {
            "path": source_rel.as_posix(),
            "sha256": sha256_bytes(source_path.read_bytes()),
        },
        "claims": copy.deepcopy(claims),
        "requests": copy.deepcopy(requests),
        "travel_cancellations": copy.deepcopy(travel_cancellations),
        "admitted_event_ids": list(admitted_event_ids),
        "issues": copy.deepcopy(issues),
    }
    errors = _schema_errors(snapshot, schema_path) + _check_semantics(snapshot)
    if errors:
        raise ValueError("Refusing to seal invalid snapshot: " + "; ".join(errors))
    serialized = json.dumps(snapshot, indent=2, ensure_ascii=False) + "\n"
    # Exclusive create prevents a concurrent run from replacing prior bytes.
    with target.open("x", encoding="utf-8", newline="\n") as stream:
        stream.write(serialized)
    errors = verify_snapshot(target, run_dir, schema_path)
    if errors:
        # Do not remove or rewrite a possibly observed sealed file. Surface the
        # integrity failure for operator investigation.
        raise ValueError("New snapshot failed post-seal integrity checks: " + "; ".join(errors))
    return target
"""Structural workflow tests use conspicuously synthetic records unless noted."""

import json
from pathlib import Path

import pytest

from travel_claim.outputs import (
    add_repair_item,
    apply_partial_response,
    load_repair_queue,
    new_repair_queue,
    owner_grouped_view,
    update_repair_item,
    write_repair_queue,
)
from travel_claim.parsing import parse_retained_run
from travel_claim.workflow import (
    build_revision_history,
    deduplicate_activity_records,
    match_decisions_to_subjects,
    reduce_cancellation_activities,
)


ROOT = Path(__file__).resolve().parents[1]
CAPTURE = ROOT / "artifacts/runs/source-capture-20261014T100034Z"


def _claim(claim_id, revision, trip_id="T-SYN-01", trip_revision="1", batch="1"):
    return {
        "source_id": "synthetic-claims",
        "source_sha256": "a" * 64,
        "locator": f"synthetic fixture claim {claim_id} revision {revision}",
        "claim_id": claim_id,
        "fields": [
            {"label": "Claim reference", "value": claim_id},
            {"label": "Revision", "value": str(revision)},
            {"label": "Trip reference", "value": trip_id},
            {"label": "Trip revision", "value": trip_revision},
            {"label": "Arrival batch", "value": batch},
        ],
        "text": f"SYNTHETIC TEST FIXTURE ONLY: {claim_id} revision {revision}",
    }


def _workbook_record(row, **values):
    return {
        "source_id": "synthetic-register",
        "source_sha256": "b" * 64,
        "locator": f"synthetic tab 'Fixture', row {row}",
        "row": row,
        "values": {key: {"value": value, "source_text": str(value), "cell": f"A{row}"}
                   for key, value in values.items()},
    }


def _cancellation_row(row, *, event_id, cancellation_id, action, target_type="permit",
                      target_id="P-SYN-01", target_revision=1, batch=1, initiation=None,
                      effective=None):
    return _workbook_record(
        row,
        **{
            "Cancellation activity reference": event_id,
            "Cancellation reference": cancellation_id,
            "Action": action,
            "Cancelled subject": target_type,
            "Trip reference": "T-SYN-01",
            "Trip revision": 1,
            "Permit reference": target_id if target_type == "permit" else None,
            "Permit revision": target_revision if target_type == "permit" else None,
            "Initiation activity reference": initiation,
            "Arrival batch": batch,
            "Effective time (UTC)": effective,
        },
    )


def test_revision_history_and_decision_matching_are_structural_only():
    # Synthetic revisions deliberately separate claim, trip, and permit version numbers.
    parsed = {
        "records": {
            "claim_revisions": [_claim("C-SYN-01", 1), _claim("C-SYN-01", 2, trip_revision="1", batch="3")],
            "trips": [
                _workbook_record(6, **{"Trip reference": "T-SYN-01", "Trip revision": 1,
                                      "Permit reference": "P-SYN-01", "Permit revision": 1}),
                _workbook_record(7, **{"Trip reference": "T-SYN-01", "Trip revision": 2,
                                      "Permit reference": "P-SYN-01", "Permit revision": 1}),
            ],
        }
    }
    history = build_revision_history(parsed)
    assert [row["revision"] for row in history["claim"]["C-SYN-01"]["revisions"]] == [1, 2]
    assert history["claim"]["C-SYN-01"]["current_revision"] == 2
    assert history["trip"]["T-SYN-01"]["current_revision"] == 2
    assert history["permit"]["P-SYN-01"]["current_revision"] == 1
    assert history["claim"]["C-SYN-01"]["revisions"][1]["trip_revision"] == 1

    decisions = [
        _workbook_record(10, **{"Decision reference": "D-SYN-OLD", "Subject type": "claim",
                                "Subject reference": "C-SYN-01", "Revision": 1, "Outcome": "approve"}),
        _workbook_record(11, **{"Decision reference": "D-SYN-UNKNOWN", "Subject type": "trip",
                                "Subject reference": "T-SYN-01", "Revision": 9, "Outcome": "return"}),
    ]
    matches = match_decisions_to_subjects(decisions, history)
    assert [row["structural_match"] for row in matches] == ["revision_match_historical", "revision_not_found"]
    assert [row["applied"] for row in matches] == [False, False]
    assert matches[0]["observed_outcome"] == "approve"  # preserved observation; no approval is performed


def test_cancellation_state_machine_keeps_trip_and_permit_processes_independent():
    events = [
        _cancellation_row(6, event_id="TC-SYN-P-REQ", cancellation_id="TC-SYN-P",
                          action="requested", target_type="permit", target_id="P-SYN-01", batch=1),
        _cancellation_row(7, event_id="TC-SYN-T-REQ", cancellation_id="TC-SYN-T",
                          action="requested", target_type="trip", target_id="T-SYN-01", batch=1),
        _cancellation_row(8, event_id="TC-SYN-P-CFM", cancellation_id="TC-SYN-P",
                          action="confirmed", target_type="permit", target_id="P-SYN-01", batch=2,
                          initiation="TC-SYN-P-REQ", effective="2026-11-16T09:00:00+01:00"),
    ]
    result = reduce_cancellation_activities(events)
    assert result["processes"]["TC-SYN-P"]["state"] == "confirmed"
    assert result["processes"]["TC-SYN-T"]["state"] == "requested"
    assert result["processes"]["TC-SYN-T"]["next_action"] == "await a linked confirmation activity"
    assert result["finance_effects"] == []
    assert result["claim_effects"] == []
    assert result["processes"]["TC-SYN-P"]["target"] == {
        "subject_type": "permit", "subject_id": "P-SYN-01", "revision": 1,
    }


def test_event_deduplication_is_replay_safe_and_flags_same_id_payload_conflicts():
    # Synthetic Finance-like event IDs; arrival batch is delivery metadata.
    first = _workbook_record(6, **{"Activity reference": "F-SYN-01", "Arrival batch": 2,
                                  "Activity type": "settled", "Amount (EUR)": 100.0,
                                  "Claim reference": "C-SYN-01"})
    replay = _workbook_record(31, **{"Activity reference": "F-SYN-01", "Arrival batch": 4,
                                    "Activity type": "settled", "Amount (EUR)": 100.0,
                                    "Claim reference": "C-SYN-01"})
    changed = _workbook_record(32, **{"Activity reference": "F-SYN-01", "Arrival batch": 4,
                                      "Activity type": "settled", "Amount (EUR)": 120.0,
                                      "Claim reference": "C-SYN-01"})
    exact = deduplicate_activity_records([first, replay], id_field="Activity reference")
    assert len(exact["unique_events"]) == 1
    assert exact["duplicates"][0]["delivery_batches"] == [2, 4]
    assert exact["conflicts"] == []
    conflict = deduplicate_activity_records([first, changed], id_field="Activity reference")
    assert conflict["unique_events"] == []
    assert conflict["conflicts"][0]["event_id"] == "F-SYN-01"


def test_actual_retained_activity_replays_are_deduplicated_and_cancellation_ids_are_separate(tmp_path):
    parsed = parse_retained_run(CAPTURE, output_path=tmp_path / "parsed.json")
    history = build_revision_history(parsed)
    c09 = history["claim"]["C09"]
    assert [(row["revision"], row["trip_id"], row["trip_revision"])
            for row in c09["revisions"]] == [(1, "T09", 1), (2, "T09B", 1)]
    assert c09["current_revision"] == 2
    matched = match_decisions_to_subjects(parsed["records"]["decisions"], history)
    assert len(matched) == 307
    assert all(row["applied"] is False for row in matched)
    assert {row["structural_match"] for row in matched} == {
        "revision_match_current", "revision_match_historical",
    }

    finance = deduplicate_activity_records(parsed["records"]["finance_events"], id_field="Activity reference")
    assert len(finance["unique_events"]) == 219
    assert finance["conflicts"] == []
    assert finance["duplicates"][0]["event_id"] == "F-C01-1"
    assert finance["duplicates"][0]["delivery_batches"] == [2.0, 4.0]

    cancellations = reduce_cancellation_activities(parsed["records"]["cancellation_activities"])
    assert len(cancellations["duplicate_events"]) == 1
    assert cancellations["duplicate_events"][0]["event_id"] == "TC122-confirmed"
    assert len(cancellations["processes"]) == 4
    assert {process["target"]["subject_type"] for process in cancellations["processes"].values()} == {"trip", "permit"}
    assert all(process["state"] == "confirmed" for process in cancellations["processes"].values())
    assert cancellations["issues"] == []
    assert cancellations["finance_effects"] == [] and cancellations["claim_effects"] == []


def test_repair_item_updates_reopen_new_revision_and_keep_owner_history(tmp_path):
    queue = new_repair_queue()
    add_repair_item(
        queue, item_id="repair-C-SYN-01-receipt", subject_type="claim", subject_id="C-SYN-01",
        revision=1, source_refs=["synthetic/receipt-register#row-1"],
        missing_or_return_reason="SYNTHETIC FIXTURE: receipt needed", owner="EMP-SYN-01",
        next_action="provide the identified receipt", run_id="run-synthetic", batch_id="batch-synthetic-1",
    )
    apply_partial_response(
        queue, response_id="response-synthetic-1",
        item_outcomes={"repair-C-SYN-01-receipt": {"outcome": "supported", "source_refs": ["synthetic/receipt#1"]}},
        run_id="run-synthetic", batch_id="batch-synthetic-2",
    )
    path = tmp_path / "repair-queue.json"
    write_repair_queue(queue, path)

    update_repair_item(
        queue, item_id="repair-C-SYN-01-receipt", update_id="update-synthetic-1",
        run_id="run-synthetic", batch_id="batch-synthetic-3", revision=2,
        source_refs=["synthetic/receipt-register#row-1", "synthetic/correction#C-SYN-01-r2"],
        missing_or_return_reason="SYNTHETIC FIXTURE: corrected revision requires evidence recheck",
        owner="ADMIN-SYN-01", next_action="recheck receipt against revision 2",
    )
    before_replay = json.dumps(queue, sort_keys=True)
    update_repair_item(
        queue, item_id="repair-C-SYN-01-receipt", update_id="update-synthetic-1",
        run_id="run-synthetic", batch_id="batch-synthetic-3", revision=2,
        source_refs=["synthetic/receipt-register#row-1", "synthetic/correction#C-SYN-01-r2"],
        missing_or_return_reason="SYNTHETIC FIXTURE: corrected revision requires evidence recheck",
        owner="ADMIN-SYN-01", next_action="recheck receipt against revision 2",
    )
    assert json.dumps(queue, sort_keys=True) == before_replay
    with pytest.raises(ValueError, match="conflicting replay"):
        update_repair_item(
            queue, item_id="repair-C-SYN-01-receipt", update_id="update-synthetic-1",
            run_id="run-synthetic", batch_id="batch-synthetic-3", owner="FIN-SYN-01",
        )
    assert queue["items"]["repair-C-SYN-01-receipt"]["status"] == "open"
    assert queue["items"]["repair-C-SYN-01-receipt"]["response_id"] is None
