    "next_action",
)


def _money(value: Any, field: str, allow_negative: bool = False) -> int | None:
    if value is None:
        return None
    if isinstance(value, bool) or not isinstance(value, int):
        raise ValueError(f"{field} must be integer cents or null")
    if not allow_negative and value < 0:
        raise ValueError(f"{field} cannot be negative")
    return value


def write_claims_csv(claims: list[dict], path: Path) -> None:
    """Write one row per supplied current claim with the required exact header."""
    ids = [claim.get("claim_id") for claim in claims]
    if any(not value for value in ids) or len(ids) != len(set(ids)):
        raise ValueError("claims must contain one nonempty, unique current row per claim_id")
    prepared = []
    for claim in sorted(claims, key=lambda row: row["claim_id"]):
        missing = set(CLAIMS_COLUMNS) - set(claim)
        if missing:
            raise ValueError(f"claim {claim.get('claim_id')} is missing CSV fields: {sorted(missing)}")
        row = {key: claim[key] for key in CLAIMS_COLUMNS}
        if isinstance(row["revision"], bool) or not isinstance(row["revision"], int) or row["revision"] < 1:
            raise ValueError(f"claim {claim['claim_id']} revision must be a positive integer")
        for key in ("claim_id", "trip_id", "status", "reason"):
            if not isinstance(row[key], str) or not row[key]:
                raise ValueError(f"{key} must be a nonempty string")
        if row["status"] not in CLAIM_STATUSES:
            raise ValueError(f"unsupported claim status {row['status']!r}")
        row["allowed_cents"] = _money(row["allowed_cents"], "allowed_cents")
        row["paid_cents"] = _money(row["paid_cents"], "paid_cents")
        row["balance_cents"] = _money(row["balance_cents"], "balance_cents", allow_negative=True)
        for key in ("next_owner", "reason"):
            if row[key] is not None and not isinstance(row[key], str):
                raise ValueError(f"{key} must be a string or null")
            row[key] = "" if row[key] is None else row[key]
        prepared.append(row)
    path.parent.mkdir(parents=True, exist_ok=True)
    with path.open("x", encoding="utf-8", newline="") as stream:
        writer = csv.DictWriter(stream, fieldnames=CLAIMS_COLUMNS, extrasaction="raise")
        writer.writeheader()
        writer.writerows(prepared)


def new_repair_queue() -> dict:
    return {"queue_version": "owner-queue/1", "items": {}, "events": []}


def add_repair_item(
    queue: dict,
    *,
    item_id: str,
    subject_type: str,
    subject_id: str,
    revision: int,
    source_refs: list[str],
    missing_or_return_reason: str,
    owner: str,
    next_action: str,
    run_id: str,
    batch_id: str,
) -> None:
    """Add a distinct open item. Request content is a local draft only."""
    if not item_id or item_id in queue["items"]:
        raise ValueError(f"repair item ID is empty or already exists: {item_id!r}")
    if subject_type not in {"claim", "trip", "permit"}:
        raise ValueError("subject_type must be claim, trip, or permit")
    if not subject_id or not owner or not missing_or_return_reason or not next_action:
        raise ValueError("subject, owner, reason, and next action are required")
    if isinstance(revision, bool) or not isinstance(revision, int) or revision < 1:
        raise ValueError("revision must be a positive integer")
    if not isinstance(source_refs, list) or not all(isinstance(ref, str) and ref for ref in source_refs):
        raise ValueError("source_refs must be a list of nonempty references")
    item = {
        "item_id": item_id,
        "subject_type": subject_type,
        "subject_id": subject_id,
        "revision": revision,
        "source_refs": list(dict.fromkeys(source_refs)),
        "missing_or_return_reason": missing_or_return_reason,
        "owner": owner,
        "next_action": next_action,
        "status": "open",
        "run_id": run_id,
        "batch_id": batch_id,
        "response_id": None,
        "resolution_source_refs": [],
        "history": [],
        "request_draft": {"status": "draft", "sent": False},
    }
    queue["items"][item_id] = item
    queue["events"].append({
        "event": "item-opened",
        "item_id": item_id,
        "run_id": run_id,
        "batch_id": batch_id,
        "status": "open",
    })


def apply_partial_response(
    queue: dict,
    *,
    response_id: str,
    item_outcomes: dict[str, dict],
    run_id: str,
    batch_id: str,
) -> None:
    """Record a supplied response against explicitly matched repair item IDs.

    Only `supported` plus at least one retained source reference resolves an
    item. Every other outcome remains open. Unmentioned items are untouched.
    """
    allowed = {"supported", "insufficient", "conflicting", "unanswered"}
    if not response_id:
        raise ValueError("response_id is required")
    if not isinstance(item_outcomes, dict):
        raise ValueError("item_outcomes must map repair item IDs to outcomes")
    planned: list[tuple[str, dict, str, list[str], dict | None]] = []
    for item_id, outcome in item_outcomes.items():
        if item_id not in queue["items"]:
            raise KeyError(f"response references unknown repair item {item_id}")
        if not isinstance(outcome, dict):
            raise ValueError(f"response outcome for {item_id} must be an object")
        kind = outcome.get("outcome")
        if kind not in allowed:
            raise ValueError(f"invalid response outcome for {item_id}: {kind!r}")
        refs = outcome.get("source_refs", [])
        if not isinstance(refs, list) or not all(isinstance(ref, str) and ref for ref in refs):
            raise ValueError(f"response source_refs must be a list of references for {item_id}")
        if kind == "supported" and not refs:
            raise ValueError(f"supported response {item_id} requires source references")
        item = queue["items"][item_id]
        if outcome.get("note") is not None and not isinstance(outcome.get("note"), str):
            raise ValueError(f"response note must be a string or null for {item_id}")
        prior_event = next(
            (event for event in reversed(queue["events"])
             if event.get("event") == "response-recorded"
             and event.get("response_id") == response_id
             and event.get("item_id") == item_id),
            None,
        )
        normalized_refs = list(dict.fromkeys(refs))
        if prior_event is not None:
            same = (
                prior_event.get("outcome") == kind
                and prior_event.get("source_refs") == normalized_refs
                and prior_event.get("note") == outcome.get("note")
            )
            if same:
                planned.append((item_id, item, kind, normalized_refs, prior_event))
                continue
            raise ValueError(f"conflicting replay for repair response {response_id}/{item_id}")
        planned.append((item_id, item, kind, normalized_refs, None))

    # Mutate only after every item in this partial response passed validation.
    for item_id, item, kind, normalized_refs, prior_event in planned:
        if prior_event is not None:
            continue
        prior = {
            "response_id": response_id,
            "outcome": kind,
            "note": item_outcomes[item_id].get("note"),
            "source_refs": normalized_refs,
            "run_id": run_id,
            "batch_id": batch_id,
            "previous_status": item["status"],
        }
        item["history"].append(prior)
        item["response_id"] = response_id
        if kind == "supported":
            item["status"] = "resolved"
            item["resolution_source_refs"] = normalized_refs
        else:
            item["status"] = "open"
        queue["events"].append({
            "event": "response-recorded",
            "item_id": item_id,
            "response_id": response_id,
            "outcome": kind,
            "note": outcome.get("note"),
            "source_refs": normalized_refs,
            "run_id": run_id,
            "batch_id": batch_id,
            "status": item["status"],
        })


def update_repair_item(
    queue: dict,
    *,
    item_id: str,
    update_id: str,
    run_id: str,
    batch_id: str,
    revision: int | None = None,
    source_refs: list[str] | None = None,
    missing_or_return_reason: str | None = None,
    owner: str | None = None,
    next_action: str | None = None,
) -> None:
    """Update a repair item's mutable trace fields without losing its history.

    Item and subject identity never change. Advancing its subject revision
    reopens the item and clears the prior resolution pointer while preserving
    the prior response and fields in the append-only history.
    """
    if not update_id:
        raise ValueError("update_id is required")
    if item_id not in queue.get("items", {}):
        raise KeyError(f"unknown repair item {item_id}")
    item = queue["items"][item_id]
    changes = {}
    if revision is not None:
        if isinstance(revision, bool) or not isinstance(revision, int) or revision < 1:
            raise ValueError("revision must be a positive integer")
        if revision < item["revision"]:
            raise ValueError("repair item revision cannot move backwards")
        changes["revision"] = revision
    if source_refs is not None:
        if not isinstance(source_refs, list) or not all(isinstance(ref, str) and ref for ref in source_refs):
            raise ValueError("source_refs must be a list of nonempty references")
        changes["source_refs"] = list(dict.fromkeys(source_refs))
    for field, value in (("missing_or_return_reason", missing_or_return_reason),
                         ("owner", owner), ("next_action", next_action)):
        if value is not None:
            if not isinstance(value, str) or not value.strip():
                raise ValueError(f"{field} must be a nonempty string")
            changes[field] = value
    replay = next((event for event in queue["events"] if event.get("event") == "item-updated"
                   and event.get("update_id") == update_id), None)
    normalized = {key: changes[key] for key in sorted(changes)}
    if replay is not None:
        if replay.get("item_id") == item_id and replay.get("changes") == normalized:
            return
        raise ValueError(f"conflicting replay for repair update {update_id}")
    if not changes:
        raise ValueError("repair item update contains no field changes")
    before = {key: item[key] for key in changes}
    if all(before[key] == changes[key] for key in changes):
        raise ValueError("repair item update does not change any field")
    history = {
        "event": "item-updated", "update_id": update_id,
        "previous": before, "changes": normalized,
        "previous_status": item["status"], "previous_response_id": item["response_id"],
        "previous_resolution_source_refs": list(item["resolution_source_refs"]),
        "run_id": run_id, "batch_id": batch_id,
    }
    item["history"].append(history)
    item.update(changes)
    if "revision" in changes and changes["revision"] != before["revision"]:
        item["status"] = "open"
        item["response_id"] = None
        item["resolution_source_refs"] = []
    queue["events"].append({
        "event": "item-updated", "item_id": item_id, "update_id": update_id,
        "changes": normalized, "run_id": run_id, "batch_id": batch_id,
        "status": item["status"],
    })


"""Schema-checked, content-addressed batch snapshots."""

from __future__ import annotations

import copy
import json
from pathlib import Path

from jsonschema import Draft202012Validator, FormatChecker

from .sources import sha256_bytes, verify_source_manifest


def _schema_errors(snapshot: dict, schema_path: Path) -> list[str]:
    schema = json.loads(schema_path.read_text(encoding="utf-8"))
    validator = Draft202012Validator(schema, format_checker=FormatChecker())
    return [
        f"{'.'.join(map(str, err.absolute_path)) or '<root>'}: {err.message}"
        for err in sorted(validator.iter_errors(snapshot), key=lambda e: list(map(str, e.absolute_path)))
    ]


def _check_semantics(snapshot: dict) -> list[str]:
    errors: list[str] = []
    issue_ids = [issue["record_id"] for issue in snapshot["issues"]]
    if len(issue_ids) != len(set(issue_ids)):
        errors.append("issues[].record_id values must be unique")
    issue_set = set(issue_ids)
    for cancellation in snapshot["travel_cancellations"]:
        missing = set(cancellation["issue_record_ids"]) - issue_set
        if missing:
            errors.append(f"cancellation {cancellation['cancellation_id']} refers to missing issue records: {sorted(missing)}")
    claim_ids = {claim["claim_id"] for claim in snapshot["claims"]}
    for request in snapshot["requests"]:
        if request["claim_id"] not in claim_ids:
            errors.append(f"request {request['request_id']} refers to missing claim {request['claim_id']}")
    cancellation_event_ids = {
        event_id
        for cancellation in snapshot["travel_cancellations"]
        for event_id in cancellation["admitted_cancellation_event_ids"]
    }
    overlap = cancellation_event_ids & set(snapshot["admitted_event_ids"])
    if overlap:
        errors.append(f"Finance admitted_event_ids must not contain cancellation activity IDs: {sorted(overlap)}")
    return errors


def verify_snapshot(snapshot_path: Path, run_dir: Path, schema_path: Path) -> list[str]:
    """Verify this snapshot and every sealed snapshot in its predecessor chain."""
    return _verify_snapshot(snapshot_path, run_dir, schema_path, set())


def _verify_snapshot(
    snapshot_path: Path,
    run_dir: Path,
    schema_path: Path,
    seen_paths: set[Path],
) -> list[str]:
    """Validate schema plus source/predecessor hashes and required references."""
    resolved_snapshot = snapshot_path.resolve()
    if resolved_snapshot in seen_paths:
        return [f"predecessor cycle detected at {snapshot_path}"]
    seen_paths.add(resolved_snapshot)
    try:
        snapshot = json.loads(snapshot_path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError) as exc:
        return [f"Cannot read snapshot: {exc}"]
    errors = _schema_errors(snapshot, schema_path)
    if errors:
        return errors
    errors.extend(_check_semantics(snapshot))
    errors.extend(verify_source_manifest(run_dir))
    try:
        manifest = json.loads((run_dir / "sources.json").read_text(encoding="utf-8"))
        if not isinstance(manifest, dict):
            raise ValueError("sources.json must be an object")
        if manifest.get("run_id") != snapshot["run_id"]:
            errors.append("snapshot run_id does not match sources.json run_id")
        files = manifest.get("files", [])
        retained_ids = {
            record.get("source_id")
            for record in files if isinstance(record, dict)
            if record.get("status") == "read"
        }
        for claim in snapshot["claims"]:
            for line in claim["lines"]:
                missing_sources = set(line["source_ids"]) - retained_ids
                if missing_sources:
                    errors.append(
                        f"claim {claim['claim_id']} cost {line['cost_id']} refers to unavailable source IDs: {sorted(missing_sources)}"
                    )
    except (OSError, json.JSONDecodeError, ValueError):
        manifest = {}
    source_binding = snapshot["source_binding"]
    source_path = run_dir / source_binding["path"]
    if not source_path.resolve().is_relative_to(run_dir.resolve()):
        errors.append("source_binding path escapes the run directory")
        return errors
    if source_path.resolve() != (run_dir / "sources.json").resolve():
        errors.append("source_binding must identify this run's sources.json")
        return errors
    try:
        actual = sha256_bytes(source_path.read_bytes())
    except OSError as exc:
        errors.append(f"Cannot read bound sources file {source_binding['path']}: {exc}")
    else:
        if actual != source_binding["sha256"]:
            errors.append("source_binding SHA-256 does not match retained sources.json")
    predecessor = snapshot["predecessor"]
    if predecessor is not None:
        previous_path = run_dir / predecessor["path"]
        if not previous_path.resolve().is_relative_to((run_dir / "batches").resolve()):
            errors.append("predecessor path escapes the run's batches directory")
            return errors
        try:
            actual = sha256_bytes(previous_path.read_bytes())
        except OSError as exc:
            errors.append(f"Cannot read predecessor {predecessor['path']}: {exc}")
        else:
            if actual != predecessor["sha256"]:
                errors.append("predecessor SHA-256 does not match retained snapshot")
            else:
                errors.extend(
                    f"predecessor chain: {error}"
                    for error in _verify_snapshot(previous_path, run_dir, schema_path, seen_paths)
                )
    return errors


def seal_batch_snapshot(
    run_dir: Path,
    *,
    run_id: str,
    batch_id: str,
    claims: list[dict],
    requests: list[dict],
    travel_cancellations: list[dict],
    admitted_event_ids: list[str],
    issues: list[dict],
    schema_path: Path,
    predecessor_path: Path | None = None,
) -> Path:
    """Seal one batch. Binding paths are relative to the run directory.

    Existing snapshots are never overwritten. The first snapshot uses a null
    predecessor; later snapshots hash the exact prior serialized bytes.
    """
    batches_dir = run_dir / "batches"
    batches_dir.mkdir(parents=True, exist_ok=True)
    if not batch_id or Path(batch_id).name != batch_id or batch_id in {".", ".."}:
        raise ValueError("batch_id must be a single safe path component")
    target = batches_dir / f"{batch_id}.json"
    if target.exists():
        raise FileExistsError(f"Refusing to overwrite sealed snapshot: {target}")
    source_path = run_dir / "sources.json"
    if not source_path.is_file():
        raise FileNotFoundError(f"Required source manifest missing: {source_path}")
    source_errors = verify_source_manifest(run_dir)
    if source_errors:
        raise ValueError("Source manifest is not integrity-valid: " + "; ".join(source_errors))
    manifest = json.loads(source_path.read_text(encoding="utf-8"))
    if manifest.get("run_id") != run_id:
        raise ValueError("Snapshot run_id must match sources.json run_id")
    if not manifest.get("case_clock"):
        raise ValueError("Cannot consume a batch without the supplied scenario case_clock")
    existing_snapshots = list(batches_dir.glob("*.json"))
    if existing_snapshots and predecessor_path is None:
        raise ValueError("A later batch must bind its predecessor snapshot")
    source_rel = Path("sources.json")
    predecessor = None
    if predecessor_path is not None:
        predecessor_path = predecessor_path.resolve()
        if not predecessor_path.is_file():
            raise FileNotFoundError(f"Predecessor snapshot missing: {predecessor_path}")
        if predecessor_path.parent.resolve() != batches_dir.resolve():
            raise ValueError("Predecessor must be a retained snapshot in this run's batches directory")
        # Verify its source binding and full schema before chaining from it.
        predecessor_errors = verify_snapshot(predecessor_path, run_dir, schema_path)
        if predecessor_errors:
            raise ValueError("Predecessor snapshot is invalid: " + "; ".join(predecessor_errors))
        prior_state = json.loads(predecessor_path.read_text(encoding="utf-8"))
        if prior_state["run_id"] != run_id:
            raise ValueError("Predecessor snapshot belongs to a different run")
        chain_paths: set[Path] = set()
        cursor = predecessor_path.resolve()
        while cursor not in chain_paths:
            chain_paths.add(cursor)
            cursor_state = json.loads(cursor.read_text(encoding="utf-8"))
            previous = cursor_state["predecessor"]
            if previous is None:
                break
            cursor = (run_dir / previous["path"]).resolve()
        existing_paths = {path.resolve() for path in existing_snapshots}
        if chain_paths != existing_paths:
            raise ValueError("Predecessor must be the end of the complete retained snapshot chain; orphaned or missing prior state found")
        predecessor = {
            "path": (Path("batches") / predecessor_path.name).as_posix(),
            "sha256": sha256_bytes(predecessor_path.read_bytes()),
        }
    snapshot = {
        "schema_version": "travel-claim-snapshot/2",
        "run_id": run_id,
        "batch_id": batch_id,
        "predecessor": predecessor,
        "source_binding": {
            "path": source_rel.as_posix(),
            "sha256": sha256_bytes(source_path.read_bytes()),
        },
        "claims": copy.deepcopy(claims),
        "requests": copy.deepcopy(requests),
        "travel_cancellations": copy.deepcopy(travel_cancellations),
        "admitted_event_ids": list(admitted_event_ids),
        "issues": copy.deepcopy(issues),
    }
    errors = _schema_errors(snapshot, schema_path) + _check_semantics(snapshot)
    if errors:
        raise ValueError("Refusing to seal invalid snapshot: " + "; ".join(errors))
    serialized = json.dumps(snapshot, indent=2, ensure_ascii=False) + "\n"
    # Exclusive create prevents a concurrent run from replacing prior bytes.
    with target.open("x", encoding="utf-8", newline="\n") as stream:
        stream.write(serialized)
    errors = verify_snapshot(target, run_dir, schema_path)
    if errors:
        # Do not remove or rewrite a possibly observed sealed file. Surface the
        # integrity failure for operator investigation.
        raise ValueError("New snapshot failed post-seal integrity checks: " + "; ".join(errors))
    return target
def _sync_decision_and_revision_issues(
    domain: dict[str, Any], *, history: dict[str, Any], run_id: str, batch_id: str,
) -> None:
    queue = domain["repair_queue"]
    blockers = []
    for conflict in history.get("issues", {}).get("repeated_subject_revisions", []):
        kind = conflict["kind"]
        subject_id = conflict["subject_id"]
        revision = conflict["revision"]
        refs = [_ref_text(ref) for ref in conflict.get("occurrences", [])]
        item_id = f"revision-conflict:{kind}:{subject_id}:r{revision}"
        _open_issue_for_subject(
            queue, item_id=item_id, subject_type=kind, subject_id=subject_id,
            revision=revision, refs=refs,
            reason=f"multiple retained source records use {kind} {subject_id} revision {revision}; their business content requires review",
            owner="Travel Administration Lead", next_action="compare the source occurrences and establish the supported revision record",
            run_id=run_id, batch_id=batch_id,
        )
    for malformed in history.get("issues", {}).get("malformed_revision_records", []):
        blockers.append({
            "record_id": f"malformed-revision:{_digest(malformed)[:16]}",
            "reason": malformed["reason"],
            "owner": "Travel Administration Lead",
            "resolution_needed": "identify the subject and revision from the native source record",
            "source_ref": malformed.get("source_ref"),
        })
    for decision in domain["decision_history"]:
        if decision["structural_match"] in {"revision_match_current", "revision_match_historical"}:
            continue
        kind, subject_id, revision = decision.get("subject_type"), decision.get("subject_id"), decision.get("revision")
        decision_id = decision.get("decision_id") or _digest(decision)[:16]
        if kind in {"claim", "trip", "permit"} and isinstance(subject_id, str) and isinstance(revision, int) and revision > 0:
            item_id = f"decision-match:{decision_id}"
            _open_issue_for_subject(
                queue, item_id=item_id, subject_type=kind, subject_id=subject_id,
                revision=revision, refs=[_ref_text(decision["decision_source_ref"])],
                reason=f"recorded decision {decision_id} does not structurally match an available {kind} revision ({decision['structural_match']})",
                owner="Travel Administration Lead", next_action="resolve the decision subject or revision against the native review ledger",
                run_id=run_id, batch_id=batch_id,
            )
        else:
            blockers.append({
                "record_id": f"decision-match:{decision_id}",
                "reason": f"recorded decision has no traceable supported subject/revision ({decision['structural_match']})",
                "owner": "Travel Administration Lead",
                "resolution_needed": "identify its subject and revision in the native review ledger",
                "source_ref": decision["decision_source_ref"],
            })
    domain["structural_blockers"] = blockers


def integrate_arrival_batch(
    parsed: dict[str, Any],
    *,
    arrival_batch: int,
    run_id: str,
    batch_id: str,
    source_binding: dict[str, str],
    predecessor: dict[str, str] | None = None,
    prior_result: dict[str, Any] | None = None,
    authorized_obligations: dict[str, dict[str, Any]] | None = None,
    source_classifications: dict[str, str] | None = None,
) -> dict[str, Any]:
    """Integrate exactly the next arrival batch into a schema-shaped projection.

    The function retains raw subject/activity rows in a sidecar `domain`,
    carries earlier state forward, and supports exact same-batch replay. It
    does not consume or seal a scenario snapshot; callers must separately
    verify access, case clock, policy, and authorities before doing that.
    """
    if isinstance(arrival_batch, bool) or not isinstance(arrival_batch, int) or arrival_batch < 1:
        raise ValueError("arrival_batch must be a positive integer")
    if not run_id or not batch_id or not isinstance(source_binding, dict):
        raise ValueError("run_id, batch_id, and source_binding are required")
    delta = _delta(parsed, arrival_batch)
    digest = _digest({
        "delta": delta,
        "run_id": run_id,
        "batch_id": batch_id,
        "source_binding": source_binding,
        "predecessor": predecessor,
        "authorized_obligations": authorized_obligations or {},
        "source_classifications": source_classifications or {},
        "trip_reference_records": parsed.get("records", {}).get("trips", []),
        "unresolved_issues": parsed.get("unresolved_issues", []),
    })
    previous_domain = deepcopy(prior_result["domain"]) if prior_result else _domain_seed()
    processed = previous_domain["processed_batches"]
    if processed and arrival_batch == processed[-1]:
        if previous_domain["batch_input_hashes"].get(str(arrival_batch)) == digest:
            return deepcopy(prior_result)
        raise ValueError(f"conflicting replay for arrival batch {arrival_batch}")
    expected_batch = processed[-1] + 1 if processed else 1
    if arrival_batch != expected_batch:
        raise ValueError(f"arrival batches must be integrated in explicit order; expected {expected_batch}, got {arrival_batch}")
    if prior_result is None and predecessor is not None:
        raise ValueError("the first integrated batch must have a null predecessor")
    if prior_result is not None:
        if prior_result.get("snapshot", {}).get("run_id") != run_id:
            raise ValueError("prior integration state belongs to a different run")
        if predecessor is None:
            raise ValueError("a later integrated batch must carry a predecessor binding")

    domain = previous_domain
    if authorized_obligations:
        domain["authorized_obligations"].update(deepcopy(authorized_obligations))
    if source_classifications:
        domain["source_classifications"].update(deepcopy(source_classifications))
    previous_claim_revisions = {
        subject_id: value["current_revision"]
        for subject_id, value in (domain.get("revision_history") or {}).get("claim", {}).items()
    }
    for name in ("claim_revisions", "decisions", "finance_events", "cancellation_activities"):
        target_name = {
            "claim_revisions": "claim_records", "decisions": "decision_records",
            "finance_events": "finance_records", "cancellation_activities": "cancellation_records",
        }[name]
        domain[target_name].extend(deepcopy(delta[name]))
    domain["processed_batches"].append(arrival_batch)
    domain["batch_input_hashes"][str(arrival_batch)] = digest

    history = build_revision_history({
        "records": {"claim_revisions": domain["claim_records"], "trips": parsed.get("records", {}).get("trips", [])}
    })
    domain["revision_history"] = history
    domain["decision_history"] = match_decisions_to_subjects(domain["decision_records"], history)
    for decision, raw in zip(domain["decision_history"], domain["decision_records"]):
        decision["arrival_batch"] = row_values(raw).get("Arrival batch")
        decision["applied"] = False
    _sync_decision_and_revision_issues(domain, history=history, run_id=run_id, batch_id=batch_id)
    _material_correction_tasks(
        domain, history=history, run_id=run_id, batch_id=batch_id,
        previous_revisions=previous_claim_revisions,
    )

    current_claims = {}
    for claim_id, record_set in history.get("claim", {}).items():
        current_revision = record_set["current_revision"]
        claim_revision = next(row for row in reversed(record_set["revisions"]) if row["revision"] == current_revision)
        current_claims[claim_id] = claim_revision
    finance_results = {}
    for claim_id, claim_revision in current_claims.items():
        record_set = history["claim"][claim_id]
        prior_finance = domain["finance_reconciliations"].get(claim_id)
        finance_results[claim_id] = reconcile_finance_events(
            domain["finance_records"], claim_id=claim_id,
            current_revision=claim_revision["revision"],
            authorized_obligation=domain["authorized_obligations"].get(claim_id),
            revision_history=record_set["revisions"],
            previous_reconciliation=prior_finance,
            source_classifications=domain["source_classifications"],
        )
    domain["finance_reconciliations"] = finance_results
    _sync_finance_repairs(domain, finance_results, run_id=run_id, batch_id=batch_id)

    # Policy and case-clock blockers are copied from parser/source evidence and
    # deliberately remain outside any fabricated claim/decision outcome.
    blockers = []
    for row in parsed.get("unresolved_issues", []):
        blocker = {
            "record_id": row["record_id"],
            "reason": row.get("reason", "Unresolved source issue"),
            "owner": row.get("owner", "Exercise facilitator"),
            "resolution_needed": row.get("next_action", "Obtain the missing authoritative evidence"),
            "subject_type": row.get("subject_type"),
            "subject_id": row.get("subject_id"),
            "affected_scope": row.get("affected_scope"),
            "evidence_needed": row.get("evidence_needed"),
        }
        blockers.append(blocker)
    domain["policy_clock_blockers"] = blockers

    cancellation_rows = _cancellation_rows(domain, history=history, run_id=run_id, batch_id=batch_id)
    schema_issues = list(blockers) + list(domain.get("structural_blockers", []))
    schema_issues.extend(_issue_from_item(item) for item in domain["repair_queue"]["items"].values() if item["status"] == "open")
    # Every cancellation issue reference must resolve in issues[].record_id.
    known_issue_ids = {issue["record_id"] for issue in schema_issues}
    for cancellation in cancellation_rows:
        cancellation["issue_record_ids"] = [
            issue_id for issue_id in cancellation["issue_record_ids"] if issue_id in known_issue_ids
        ]

    snapshot_claims = []
    projection_issues = []
    for claim_id, revision_row in sorted(current_claims.items()):
        revision = revision_row["revision"]
        record = revision_row["record"]
        values = _page_values(record)
        trip_id = revision_row.get("trip_id")
        trip_revision = revision_row.get("trip_revision")
        if not trip_id or not trip_revision:
            projection_issues.append({
                "record_id": f"snapshot-claim-link:{claim_id}:r{revision}",
                "reason": "claim source lacks the trip identity or revision required by snapshot.schema.json; claim omitted from snapshot projection",
                "owner": "Travel Administration Lead",
                "resolution_needed": "obtain and verify the current claim-to-trip revision binding",
            })
            continue
        trip_record_set = history.get("trip", {}).get(str(trip_id), {})
        linked_trip = any(row["revision"] == trip_revision for row in trip_record_set.get("revisions", []))
        if not linked_trip:
            item_id = f"trip-link:{claim_id}:r{revision}"
            _open_issue_for_subject(
                domain["repair_queue"], item_id=item_id, subject_type="claim", subject_id=claim_id,
                revision=revision, refs=[_ref_text(revision_row["source_ref"])],
                reason=f"claim references trip {trip_id} revision {trip_revision}, which is not present in the retained trip register",
                owner="Travel Administration Lead", next_action="verify the trip revision from an accessible native travel register",
                run_id=run_id, batch_id=batch_id,
            )
            schema_issues.append(_issue_from_item(domain["repair_queue"]["items"][item_id]))
        matches = [row for row in domain["decision_history"]
                   if row.get("subject_type") == "claim" and row.get("subject_id") == claim_id
                   and row.get("revision") == revision and row.get("structural_match") == "revision_match_current"]
        finance = finance_results[claim_id]
        snapshot_claims.append({
            "claim_id": claim_id,
            "revision": revision,
            "trip_id": str(trip_id),
            "trip_revision": trip_revision,
            "status": "pending",
            "lines": [],
            "allowed_cents": None,
            "paid_cents": finance["net_confirmed_cents"],
            "balance_cents": finance["balance_cents"],
            "decision_ids": list(dict.fromkeys(row["decision_id"] for row in matches if row.get("decision_id"))),
            "next_owner": "Travel Administration Lead",
            "reason": "Structural integration only; reimbursement policy and current-revision compliance remain unresolved.",
        })

    schema_issues.extend(projection_issues)
    schema_issues.extend(domain.get("projection_issues", []))
    # Deduplicate by record_id while preserving issue order.
    unique_issues = {}
    for issue in schema_issues:
        unique_issues.setdefault(issue["record_id"], issue)
    schema_issues = list(unique_issues.values())

    finance_ids = []
    unresolved_ids = set()
    conflicting_ids = set()
    for result in finance_results.values():
        unresolved_ids.update(result["unresolved_event_ids"])
        conflicting_ids.update(issue["event_id"] for issue in result["conflicting_events"])
        for event in result["event_history"]:
            event_id = event["event_id"]
            if (event_id and event_id not in unresolved_ids and event_id not in conflicting_ids
                    and event["classification"] not in {"unresolved", "conflicting_event_id", "missing_event_id"}):
                finance_ids.append(event_id)
    finance_ids = list(dict.fromkeys(event_id for event_id in finance_ids if event_id not in unresolved_ids | conflicting_ids))

    snapshot = {
        "schema_version": "travel-claim-snapshot/2",
        "run_id": run_id,
        "batch_id": batch_id,
        "predecessor": deepcopy(predecessor),
        "source_binding": deepcopy(source_binding),
        "claims": snapshot_claims,
        "requests": [],
        "travel_cancellations": cancellation_rows,
        "admitted_event_ids": finance_ids,
        "issues": schema_issues,
    }
    domain["processed_batches"] = list(domain["processed_batches"])
    return {
        "snapshot": snapshot,
        "domain": domain,
        "decision_history": deepcopy(domain["decision_history"]),
        "finance_reconciliations": deepcopy(finance_results),
        "revision_history": deepcopy(history),
        "repair_queue_by_owner": _owner_view(domain["repair_queue"]),
        "batch_delta_counts": {key: len(value) for key, value in delta.items()},
        "input_sha256": digest,
    }


def _owner_view(queue: dict[str, Any]) -> dict[str, list[dict[str, Any]]]:
    grouped: dict[str, list[dict[str, Any]]] = {}
    for item in queue["items"].values():
        grouped.setdefault(item["owner"], []).append(item)
    return {owner: sorted(items, key=lambda row: row["item_id"]) for owner, items in sorted(grouped.items())}
